head.script:
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vBzProcsNo;
scwin.vIsurCd;
scwin.vSecugrpID = SECUGRP_ID_EW; // (elw)메뉴단에서 파라미터로 받자..
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        $c.elw.fn_searchCode();
        await scwin.setInstCdComboCode();
        //    dts_UDWRT_INST_CD.DataID = "/CodeAction.do?method=listInstCd&For=";
        //    dts_UDWRT_INST_CD.Reset();
        $c.stf.copyDataSet(dts_INST_CD, dts_UDWRT_INST_CD);
        $c.stf.copyDataSet(dts_INST_CD, dts_PAY_BK_INST_CD);
        $c.stf.copyDataSet(dts_INST_CD, dts_BZAGNT_INST_CD);
        $c.stf.copyDataSet(dts_INST_CD, dts_DEPO_INST_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_CD_onclick
 * @description 「search」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsuCd;
        scwin.fn_SetPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindIsu(scwin.vSecugrpID);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05923.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name img_PAY_DD_onclick
 * @description img_PAY_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_PAY_DD_onclick = function() {
    try {
        popUpCalendar2(edt_PAY_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05923.img_PAY_DD_onclick" });
    }
};

