/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05923.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
