///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setInstCdComboCode
 * @description set Inst Cd Combo Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setInstCdComboCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_INST_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_INST_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_LEADCOM_MBR_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_LEADCOM_MBR_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    let url;
    url += "&SECUGRP_ID=" + scwin.vSecugrpID;
    url += "&P_KEY=" + txb_SearchCd.getValue();
    url += "&SCREN_ID=" + "ULDSTF05923.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/IssueBook.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&P_KEY=" + txb_SearchCd.getValue();
    const sbmOptions2 = {
        id : "sbm_dts_LP",
        action : "/IssueBook.do",
        ref : "",
        target : "dts_LP=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&P_KEY=" + txb_SearchCd.getValue();
    const sbmOptions3 = {
        id : "sbm_dts_UlyIsu",
        action : "/IssueBook.do",
        ref : "",
        target : "dts_UlyIsu=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB === "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB === "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB === "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     SECUGRP_ID : scwin.vSecugrpID,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISUR_CD : scwin.vIsurCd,
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_309
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/IssueBook.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_SearchNm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsuCd = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_SearchCd.setValue(arrPar[0].ISU_CD);
        txb_SearchNm.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        await scwin.readSync(txb_SearchCd.getValue());
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    // if (! dts_Isu.IsUpdated) {
    // fn_alertNoUpdate() ;return false;
    // }

    return true;
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);

        // alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            await scwin.trs(TR_JOB_UPDATE);
        }
    }
};
